const data=window.CATALOG;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let filtered=data,page=1;const size=24;
const brands=[...new Set(data.map(p=>p.brand))];
$('#brandCount').textContent=brands.length;$('#totalCount').textContent=data.length;
brands.forEach(b=>{const o=document.createElement('option');o.value=b;o.textContent=`${b}（${data.filter(p=>p.brand===b).length}）`;$('#brand').append(o)});
const hero=data.find(p=>p.image&&p.name.includes('面霜'))||data.find(p=>p.image);if(hero){$('#heroImage').src=hero.image;$('#heroImage').alt=hero.name}
function render(){const q=$('#search').value.trim().toLowerCase(),b=$('#brand').value,f=$('#form').value;filtered=data.filter(p=>(!b||p.brand===b)&&(!f||p.form.includes(f))&&(!q||[p.name,p.brand,p.brandFull,p.spec,p.category,p.id].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages);$('#results').textContent=`${b||'全部产品'} · ${filtered.length} 条`;$('#empty').hidden=filtered.length>0;$('#products').innerHTML=filtered.slice((page-1)*size,page*size).map(p=>`<button class="card" data-id="${p.id}" aria-label="查看 ${esc(p.name)} 详情"><div class="picture">${p.image?`<img src="${p.image}" alt="${esc(p.name)}" loading="lazy" width="320" height="320">`:'<span class="placeholder">暂无图片</span>'}${p.form?`<span class="tag">${esc(p.form)}</span>`:''}</div><span class="card-brand">${esc(p.brand)}</span><h3>${esc(p.name)}</h3><p class="spec">${esc(p.spec||'规格待确认')}</p><span class="card-bottom">查看详情 ↗</span></button>`).join('');$('#page').textContent=`${page} / ${pages}`;$('#prev').disabled=page===1;$('#next').disabled=page===pages;}
$('#filters').addEventListener('submit',e=>e.preventDefault());['#search','#brand','#form'].forEach(s=>$(s).addEventListener(s==='#search'?'input':'change',()=>{page=1;render()}));
$('#filters').addEventListener('reset',()=>{setTimeout(()=>{page=1;render()},0)});$('#clearEmpty').onclick=()=>$('#filters').reset();
$('#prev').onclick=()=>{page--;render();$('#catalog').scrollIntoView()};$('#next').onclick=()=>{page++;render();$('#catalog').scrollIntoView()};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
$('#products').addEventListener('click',e=>{const card=e.target.closest('[data-id]');if(!card)return;const p=data.find(x=>x.id===card.dataset.id);$('#detailBody').innerHTML=`<div>${p.image?`<img class="detail-image" src="${p.image}" alt="${esc(p.name)}">`:'<div class="picture"><span class="placeholder">暂无图片</span></div>'}</div><div><p class="eyebrow">${esc(p.brand)} / ${p.id}</p><h2 id="detailTitle">${esc(p.name)}</h2><dl>${[['规格 / 色号',p.spec],['包装类型',p.form],['产品类别',p.category]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'原资料未提供，待确认')}</dd>`).join('')}</dl><p class="detail-note">图片供选品参考，具体包装与供货信息请确认。</p><button class="copy">复制产品信息</button></div>`;$('#detail').showModal();$('.copy').onclick=async()=>{const text=`${p.brand}\n${p.name}\n规格：${p.spec||'待确认'}\n编号：${p.id}`;try{await navigator.clipboard.writeText(text);toast('产品信息已复制')}catch{toast('复制不可用，请手动选择产品信息')}}});
$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});
$('#download').onclick=()=>{const csvCell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['编号','品牌','产品名称','规格 / 色号','包装类型','产品类别'],...filtered.map(p=>[p.id,p.brand,p.name,p.spec,p.form,p.category])];const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='美妆产品清单.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出 ${filtered.length} 条产品记录`)};
render();
